// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 1 ether);

        // adversarial counterparty: a contract with no receive/fallback that
        // refuses ether, so the low-level call in withdrawBalance fails
        RevertingUser user = new RevertingUser();

        vm.deal(address(user), amount);
        vm.prank(address(user));
        c.addToBalance{value: amount}();
        require(c.getBalance(address(user)) == amount, "deposit failed");

        // withdrawal attempt: payout to `user` always fails (no payable hook)
        user.tryWithdraw(c);

        // General rule: a failed withdrawal must not destroy the balance.
        // Reference C reverts -> balance preserved. Mutant zeroes it.
        assertTrue(c.getBalance(address(user)) == amount);
    }
}

contract RevertingUser {
    Reentrance internal target;

    function tryWithdraw(Reentrance t) external {
        target = t;
        (bool ok, ) = address(this).call(abi.encodeWithSignature("doWithdraw()"));
        ok; // ignore: the inner call reverts because the ether transfer reverts
    }

    function doWithdraw() external {
        target.withdrawBalance();
    }
    // deliberately NO receive/fallback: any ether transfer to this contract reverts
}
